    public async Task<Result<int>> Handle(DeleteSubsystemCommand request, CancellationToken cancellationToken)
    {
        await using var db = await _dbContextFactory.CreateAsync(cancellationToken);
        var items = await db.Subsystems.Where(x => request.Id.Contains(x.Id)).ToListAsync(cancellationToken);
        
        if (items.Count == 0)
